package br.com.catalogo;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.awt.*;import java.util.concurrent.atomic.*;import javax.swing.*;
@EnabledIfSystemProperty(named="catalogo.guiTest",matches="true")
class LibrarySwitchTest {
 @TempDir Path root;
 @Test void switchingWindowKeepsBothBanksAndRemembersTheSelection()throws Exception{
  String old=System.getProperty("catalogo.libraries"),oldConfig=System.getProperty("catalogo.config");System.setProperty("catalogo.libraries",root.resolve("settings.json").toString());System.setProperty("catalogo.config",root.resolve("http.json").toString());var first=new LibrarySettings.Profile(root.resolve("A"),"first.db");var second=new LibrarySettings.Profile(root.resolve("B"),"second.sqlite");var lib=first.open();OrganizerTest.pdf(lib.root.resolve("Kotlin.pdf"),"Kotlin Essentials");new LibraryOrganizer(lib).organize((p,m)->{});var b=lib.books().get(0);b.notes="Preservar ao alternar";lib.save(b);LibrarySettings.activate(first);AtomicReference<CatalogoApp> app=new AtomicReference<>();
  try{SwingUtilities.invokeAndWait(()->{try{UiTheme.install();app.set(new CatalogoApp(lib,false));app.get().setVisible(true);app.get().switchTo(second);}catch(Exception e){throw new RuntimeException(e);}});long until=System.currentTimeMillis()+15000;boolean switched=false;while(System.currentTimeMillis()<until){AtomicBoolean found=new AtomicBoolean();SwingUtilities.invokeAndWait(()->{for(var w:Window.getWindows())if(w instanceof CatalogoApp next&&next.isVisible()&&next.library.database.equals(second.file()))found.set(true);});if(found.get()){switched=true;break;}Thread.sleep(40);}assertTrue(switched);assertEquals(second,LibrarySettings.read().active());assertTrue(second.open().books().isEmpty());assertEquals("Preservar ao alternar",first.open().books().get(0).notes);SwingUtilities.invokeAndWait(()->assertFalse(app.get().isDisplayable()));}
  finally{SwingUtilities.invokeAndWait(()->{for(var w:Window.getWindows())if(w instanceof CatalogoApp a){a.closed=true;a.searchDelay.stop();a.autoSave.stop();if(a.searchWorker!=null)a.searchWorker.cancel(false);a.dispose();}});if(old==null)System.clearProperty("catalogo.libraries");else System.setProperty("catalogo.libraries",old);if(oldConfig==null)System.clearProperty("catalogo.config");else System.setProperty("catalogo.config",oldConfig);}
 }
}
